import type { GridSpec } from '@melina/shared';
import data from '../../../content/art/specs.json';

export interface ArtStyle {
  name: string;
  summary: string;
  palette: string[];
  always: string[];
  never: string[];
}

export interface ArtSpec {
  id: string;
  /** clip: short video (MP4 or WebM, no sound, looping), coming from a pack; not generated by the app */
  kind: 'background' | 'prop' | 'character' | 'clip';
  title: string;
  size: [number, number];
  transparent: boolean;
  brief: string;
  mustNot: string[];
  fallback: string;
  usedBy: string[];
  grid?: GridSpec;
  /** master image of a character: the other poses use it as a reference */
  master?: boolean;
  /** spec whose approved art is sent as the reference image in the prompt */
  reference?: string;
  /**
   * The piece is drawn by code (CSS) in the game. Without an approved version, the game keeps that drawing;
   * `fallback` only illustrates the spec in the studio.
   */
  drawnByCode?: boolean;
}

export const artStyle = data.style as ArtStyle;
export const artSpecs = data.specs as unknown as ArtSpec[];

export function getArtSpec(id: string): ArtSpec | undefined {
  return artSpecs.find((s) => s.id === id);
}

/** Consistency problems in the specs (used in tests and at startup). */
export function specProblems(specs: ArtSpec[] = artSpecs): string[] {
  const out: string[] = [];
  const ids = new Set<string>();
  for (const s of specs) {
    if (!/^[a-z0-9_]+(\.[a-z0-9_]+)+$/.test(s.id)) out.push(`${s.id} : identifiant invalide`);
    if (ids.has(s.id)) out.push(`${s.id} : en double`);
    ids.add(s.id);
    const [w, h] = s.size;
    if (!(w % 16 === 0 && h % 16 === 0 && w >= 256 && h >= 256 && w <= 3840 && h <= 3840 && w / h <= 3 && h / w <= 3)) out.push(`${s.id} : taille ${w}×${h} non acceptée (multiples de 16, proportions jusqu’à 3:1)`);
    if (!s.fallback.startsWith('/art/')) out.push(`${s.id} : art intégré en dehors de /art/`);
    if (s.brief.trim().length < 20) out.push(`${s.id} : description trop courte`);
    if (s.reference && !specs.some((x) => x.id === s.reference)) out.push(`${s.id} : la référence ${s.reference} n’existe pas`);
    if (s.grid && (s.grid.inset.length !== 4 || s.grid.inset.some((v) => v < 0 || v > 0.45))) out.push(`${s.id} : marges de la grille invalides`);
    if (s.kind === 'clip' && (s.grid || s.transparent || s.drawnByCode)) out.push(`${s.id} : un clip ne peut avoir ni grille, ni transparence, ni dessin par code`);
  }
  return out;
}
